using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionAreaAlliesOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionAreaAllies Omen Logic")]
public class BattleActionAreaAlliesOmenLogic : OmenLogic
{
	[Header("Enemies")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		List<GameObject> list = currentCompanions.ActiveCompanions.Duplicate();
		list.Add(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		battleAction.AreaCastTargetAmount(list, actionValue, source);
	}
}
